=== FILE: rtl/axil_timer.v ===
`timescale 1ns/1ps
// axil_timer: AXI4-Lite timer peripheral with interrupt.
// Implements microarchitecture_spec.md (prj-ada3a9b9d9:microarchitecture).
// Single clock (aclk, rising edge), synchronous active-low reset (aresetn).
module axil_timer #(
  parameter integer ADDR_WIDTH = 4
) (
  input  wire                  aclk,
  input  wire                  aresetn,
  input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
  input  wire                  s_axil_awvalid,
  output wire                  s_axil_awready,
  input  wire [31:0]           s_axil_wdata,
  input  wire [3:0]            s_axil_wstrb,
  input  wire                  s_axil_wvalid,
  output wire                  s_axil_wready,
  output wire [1:0]            s_axil_bresp,
  output wire                  s_axil_bvalid,
  input  wire                  s_axil_bready,
  input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
  input  wire                  s_axil_arvalid,
  output wire                  s_axil_arready,
  output wire [31:0]           s_axil_rdata,
  output wire [1:0]            s_axil_rresp,
  output wire                  s_axil_rvalid,
  input  wire                  s_axil_rready,
  output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;
  localparam [1:0] SEL_CTRL    = 2'd0;
  localparam [1:0] SEL_LOAD    = 2'd1;
  localparam [1:0] SEL_COUNT   = 2'd2;
  localparam [1:0] SEL_STATUS  = 2'd3;
  localparam integer EXT_PAD   = 9 - ADDR_WIDTH;

  // ---------------------------------------------------------------- state
  reg                  aw_held;
  reg                  w_held;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [31:0]           rdata_q;
  reg [1:0]            rresp_q;
  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;
  reg                  expired_q;

  // ---------------------------------------------------------------- handshakes
  assign s_axil_awready = ~aw_held & ~bvalid_q;
  assign s_axil_wready  = ~w_held  & ~bvalid_q;
  assign s_axil_arready = ~rvalid_q;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rdata   = rdata_q;
  assign s_axil_rresp   = rresp_q;
  assign irq            = expired_q & ie_q;

  wire aw_fire = s_axil_awvalid & s_axil_awready;
  wire w_fire  = s_axil_wvalid  & s_axil_wready;
  wire ar_fire = s_axil_arvalid & s_axil_arready;
  wire wr_fire = (aw_held | aw_fire) & (w_held | w_fire);

  wire aw_held_n = ~wr_fire & (aw_held | aw_fire);
  wire w_held_n  = ~wr_fire & (w_held  | w_fire);

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
  wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

  // ---------------------------------------------------------------- decode
  wire [8:0] wr_addr_ext = {{EXT_PAD{1'b0}}, wr_addr};
  wire [8:0] rd_addr_ext = {{EXT_PAD{1'b0}}, s_axil_araddr};
  wire       wr_mapped   = (wr_addr_ext[1:0] == 2'b00) && (wr_addr_ext[8:4] == 5'd0);
  wire       rd_mapped   = (rd_addr_ext[1:0] == 2'b00) && (rd_addr_ext[8:4] == 5'd0);
  wire [1:0] wr_sel      = wr_addr_ext[3:2];
  wire [1:0] rd_sel      = rd_addr_ext[3:2];

  wire [1:0] wr_resp = (!wr_mapped || (wr_sel == SEL_COUNT)) ? RESP_SLVERR : RESP_OKAY;

  // ---------------------------------------------------------------- write strobes
  wire wr_hit  = wr_fire & wr_mapped;
  wire ctrl_wr = wr_hit & (wr_sel == SEL_CTRL) & wr_strb[0];
  wire load_wr = wr_hit & (wr_sel == SEL_LOAD);
  wire clr     = wr_hit & (wr_sel == SEL_STATUS) & wr_strb[0] & wr_data[0];
  wire end_e   = en_q & (count_q[31:1] == 31'd0);
  wire start   = ctrl_wr & wr_data[0];

  // ---------------------------------------------------------------- next state
  wire en_n      = ctrl_wr ? wr_data[0] : ((end_e & ~mode_q) ? 1'b0 : en_q);
  wire ie_n      = ctrl_wr ? wr_data[1] : ie_q;
  wire mode_n    = ctrl_wr ? wr_data[2] : mode_q;
  wire expired_n = end_e ? 1'b1 : (clr ? 1'b0 : expired_q);
  wire bvalid_n  = wr_fire ? 1'b1 : ((bvalid_q & s_axil_bready) ? 1'b0 : bvalid_q);
  wire rvalid_n  = ar_fire ? 1'b1 : ((rvalid_q & s_axil_rready) ? 1'b0 : rvalid_q);

  wire [31:0] load_n;
  assign load_n[7:0]   = (load_wr & wr_strb[0]) ? wr_data[7:0]   : load_q[7:0];
  assign load_n[15:8]  = (load_wr & wr_strb[1]) ? wr_data[15:8]  : load_q[15:8];
  assign load_n[23:16] = (load_wr & wr_strb[2]) ? wr_data[23:16] : load_q[23:16];
  assign load_n[31:24] = (load_wr & wr_strb[3]) ? wr_data[31:24] : load_q[31:24];

  reg [31:0] count_n;
  always @* begin
    if (start) begin
      count_n = load_q;
    end else if (end_e) begin
      count_n = mode_q ? load_q : 32'd0;
    end else if (en_q) begin
      count_n = count_q - 32'd1;
    end else begin
      count_n = count_q;
    end
  end

  // Read mux over pre-edge flop values.
  reg [31:0] rd_data_mux;
  reg [1:0]  rd_resp_mux;
  always @* begin
    rd_data_mux = 32'd0;
    rd_resp_mux = RESP_SLVERR;
    if (rd_mapped) begin
      rd_resp_mux = RESP_OKAY;
      case (rd_sel)
        SEL_CTRL:   rd_data_mux = {29'd0, mode_q, ie_q, en_q};
        SEL_LOAD:   rd_data_mux = load_q;
        SEL_COUNT:  rd_data_mux = count_q;
        SEL_STATUS: rd_data_mux = {31'd0, expired_q};
        default:    rd_data_mux = 32'd0;
      endcase
    end
  end

  // ---------------------------------------------------------------- registers
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held   <= 1'b0;
      w_held    <= 1'b0;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_data_q  <= 32'd0;
      w_strb_q  <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rdata_q   <= 32'd0;
      rresp_q   <= RESP_OKAY;
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
      expired_q <= 1'b0;
    end else begin
      aw_held   <= aw_held_n;
      w_held    <= w_held_n;
      if (aw_fire) begin
        aw_addr_q <= s_axil_awaddr;
      end
      if (w_fire) begin
        w_data_q <= s_axil_wdata;
        w_strb_q <= s_axil_wstrb;
      end
      bvalid_q  <= bvalid_n;
      if (wr_fire) begin
        bresp_q <= wr_resp;
      end
      rvalid_q  <= rvalid_n;
      if (ar_fire) begin
        rdata_q <= rd_data_mux;
        rresp_q <= rd_resp_mux;
      end
      en_q      <= en_n;
      ie_q      <= ie_n;
      mode_q    <= mode_n;
      load_q    <= load_n;
      count_q   <= count_n;
      expired_q <= expired_n;
    end
  end

`ifdef FORMAL
  // Design-intent invariants (not proven: no formal_spec is submitted).
  reg f_reset_seen = 1'b0;
  always @(posedge aclk) if (!aresetn) f_reset_seen <= 1'b1;
  always @(*) begin
    if (f_reset_seen) begin
      assert (!(aw_held && w_held));
      assert (!(bvalid_q && (aw_held || w_held)));
    end
  end
`endif

endmodule
=== END FILE ===
