`timescale 1ns/1ps
// Self-checking directed testbench for axil_timer.
// Convention: inputs change at negedge; the next posedge is the "effect edge".
// cyc counts posedges; at a negedge the next edge has index cyc+1.
module tb_axil_timer;
  localparam integer AW = 4;
  localparam [AW-1:0] A_CTRL   = 4'h0;
  localparam [AW-1:0] A_LOAD   = 4'h4;
  localparam [AW-1:0] A_COUNT  = 4'h8;
  localparam [AW-1:0] A_STATUS = 4'hC;
  localparam [1:0] OKAY   = 2'b00;
  localparam [1:0] SLVERR = 2'b10;

  reg           aclk;
  reg           aresetn;
  reg  [AW-1:0] awaddr;
  reg           awvalid;
  wire          awready;
  reg  [31:0]   wdata;
  reg  [3:0]    wstrb;
  reg           wvalid;
  wire          wready;
  wire [1:0]    bresp;
  wire          bvalid;
  reg           bready;
  reg  [AW-1:0] araddr;
  reg           arvalid;
  wire          arready;
  wire [31:0]   rdata;
  wire [1:0]    rresp;
  wire          rvalid;
  reg           rready;
  wire          irq;

  axil_timer #(.ADDR_WIDTH(AW)) dut (
    .aclk(aclk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
    .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
    .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready),
    .irq(irq)
  );

  integer passed;
  integer failed;
  integer j;
  reg [31:0] cyc = 32'd0;
  reg [31:0] wr_edge;
  reg [31:0] rd_edge;
  reg [31:0] e_start;
  reg [31:0] e2;
  reg [31:0] s_edge;
  reg [31:0] held;
  reg [31:0] rises0;
  reg [31:0] falls0;
  reg [1:0]  last_bresp;
  reg [1:0]  rd_resp;
  reg [31:0] rd_data;
  reg [8*64-1:0] nonce;

  // irq monitor (sole writer of these)
  reg        irq_d     = 1'b0;
  reg [31:0] irq_rise  = 32'd0;
  reg [31:0] irq_fall  = 32'd0;
  reg [31:0] irq_rises = 32'd0;
  reg [31:0] irq_falls = 32'd0;

  initial aclk = 1'b0;
  always #5 aclk = ~aclk;
  always @(posedge aclk) cyc <= cyc + 32'd1;

  always @(negedge aclk) begin
    if (irq === 1'b1 && irq_d === 1'b0) begin
      irq_rise  = cyc;
      irq_rises = irq_rises + 32'd1;
    end
    if (irq === 1'b0 && irq_d === 1'b1) begin
      irq_fall  = cyc;
      irq_falls = irq_falls + 32'd1;
    end
    irq_d = irq;
  end

  // ------------------------------------------------------------ checks
  task chk;
    input cond;
    input [8*64-1:0] msg;
    begin
      if (cond === 1'b1) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("CHECK FAILED at edge %0d: %0s", cyc, msg);
      end
    end
  endtask

  task chk_eq;
    input [31:0] got;
    input [31:0] exp;
    input [8*64-1:0] msg;
    begin
      if (got === exp) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("CHECK FAILED at edge %0d: %0s: got %h expected %h", cyc, msg, got, exp);
      end
    end
  endtask

  function [31:0] exp_one;
    input [31:0] n;
    input [31:0] kk;
    begin
      if (kk < n) exp_one = n - kk;
      else exp_one = 32'd0;
    end
  endfunction

  function [31:0] exp_per;
    input [31:0] n;
    input [31:0] kk;
    begin
      exp_per = n - (kk % n);
    end
  endfunction

  task wait_cycles;
    input integer n;
    begin
      repeat (n) @(negedge aclk);
    end
  endtask

  task wait_for_edge;
    input [31:0] target;
    begin
      if (target < cyc + 32'd1) begin
        failed = failed + 1;
        $error("testbench timing: edge %0d already passed (now %0d)", target, cyc);
      end else begin
        while (cyc + 32'd1 != target) @(negedge aclk);
      end
    end
  endtask

  // ------------------------------------------------------------ bus tasks
  task do_write;
    input [AW-1:0] addr;
    input [31:0]   data;
    input [3:0]    strb;
    input integer  bwait;
    input [1:0]    exp_resp;
    integer n;
    begin
      awaddr = addr; wdata = data; wstrb = strb;
      awvalid = 1'b1; wvalid = 1'b1;
      chk(awready === 1'b1 && wready === 1'b1, "write: awready and wready high when idle");
      wr_edge = cyc + 32'd1;
      @(negedge aclk);
      awvalid = 1'b0; wvalid = 1'b0;
      chk(bvalid === 1'b1, "write: bvalid high after the completing edge");
      if (bresp !== exp_resp) $error("bresp got %b expected %b (addr %h)", bresp, exp_resp, addr);
      chk(bresp === exp_resp, "write: bresp as expected");
      last_bresp = bresp;
      for (n = 0; n < bwait; n = n + 1) begin
        @(negedge aclk);
        chk(bvalid === 1'b1 && bresp === last_bresp, "write: B stable under back-pressure");
        chk(awready === 1'b0 && wready === 1'b0, "write: no write accepted while B waits");
      end
      bready = 1'b1;
      @(negedge aclk);
      bready = 1'b0;
      chk(bvalid === 1'b0, "write: bvalid low after the B handshake");
      chk(awready === 1'b1 && wready === 1'b1, "write: ready again after the B handshake");
    end
  endtask

  task do_read;
    input [AW-1:0] addr;
    input integer  rwait;
    integer n;
    begin
      araddr = addr; arvalid = 1'b1;
      chk(arready === 1'b1, "read: arready high when idle");
      rd_edge = cyc + 32'd1;
      @(negedge aclk);
      arvalid = 1'b0;
      chk(rvalid === 1'b1, "read: rvalid high after the accepting edge");
      rd_data = rdata; rd_resp = rresp;
      for (n = 0; n < rwait; n = n + 1) begin
        @(negedge aclk);
        chk(rvalid === 1'b1 && rdata === rd_data && rresp === rd_resp, "read: R stable under back-pressure");
        chk(arready === 1'b0, "read: no read accepted while R waits");
      end
      rready = 1'b1;
      @(negedge aclk);
      rready = 1'b0;
      chk(rvalid === 1'b0, "read: rvalid low after the R handshake");
      chk(arready === 1'b1, "read: arready high after the R handshake");
    end
  endtask

  task chk_read;
    input [AW-1:0]   addr;
    input [31:0]     exp_data;
    input [1:0]      exp_resp;
    input [8*64-1:0] msg;
    begin
      do_read(addr, 0);
      if (rd_data === exp_data && rd_resp === exp_resp) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("CHECK FAILED at edge %0d: %0s: addr %h got %h/%b expected %h/%b",
               cyc, msg, addr, rd_data, rd_resp, exp_data, exp_resp);
      end
    end
  endtask

  // ------------------------------------------------------------ sequence
  initial begin
    passed = 0; failed = 0;
    aresetn = 1'b0;
    awaddr = {AW{1'b0}}; awvalid = 1'b0; wdata = 32'd0; wstrb = 4'd0; wvalid = 1'b0;
    bready = 1'b0; araddr = {AW{1'b0}}; arvalid = 1'b0; rready = 1'b0;
    repeat (3) @(negedge aclk);
    aresetn = 1'b1;

    // T1 reset state
    chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, "reset: readies high");
    chk(bvalid === 1'b0 && rvalid === 1'b0, "reset: valids low");
    chk(irq === 1'b0, "reset: irq low");
    chk_read(A_CTRL,   32'h0, OKAY, "reset CTRL");
    chk_read(A_LOAD,   32'h0, OKAY, "reset LOAD");
    chk_read(A_COUNT,  32'h0, OKAY, "reset COUNT");
    chk_read(A_STATUS, 32'h0, OKAY, "reset STATUS");

    // T2 LOAD and byte strobes, B back-pressure
    do_write(A_LOAD, 32'h11223344, 4'hF, 0, OKAY);
    chk_read(A_LOAD, 32'h11223344, OKAY, "LOAD full write");
    do_write(A_LOAD, 32'hAABBCCDD, 4'b0101, 2, OKAY);
    chk_read(A_LOAD, 32'h11BB33DD, OKAY, "LOAD strobe 0101");
    do_write(A_LOAD, 32'hFFFFFFFF, 4'b0000, 0, OKAY);
    chk_read(A_LOAD, 32'h11BB33DD, OKAY, "LOAD empty strobe");
    do_write(A_LOAD, 32'h55667788, 4'b1010, 3, OKAY);
    chk_read(A_LOAD, 32'h55BB77DD, OKAY, "LOAD strobe 1010");

    // T3 CTRL fields and strobe
    do_write(A_CTRL, 32'hFFFFFFFA, 4'hF, 0, OKAY);
    chk_read(A_CTRL, 32'h2, OKAY, "CTRL upper bits ignored");
    do_write(A_CTRL, 32'h7, 4'b1110, 0, OKAY);
    chk_read(A_CTRL, 32'h2, OKAY, "CTRL wstrb[0]=0 changes nothing");
    do_write(A_CTRL, 32'h0, 4'hF, 0, OKAY);
    chk_read(A_CTRL, 32'h0, OKAY, "CTRL cleared");

    // T4 error responses
    do_write(A_COUNT, 32'h1234, 4'hF, 0, SLVERR);
    chk_read(A_COUNT, 32'h0, OKAY, "COUNT write changes nothing");
    do_write(4'h1, 32'h7, 4'hF, 0, SLVERR);
    chk_read(A_CTRL, 32'h0, OKAY, "misaligned write does not alias CTRL");
    do_write(4'h6, 32'hFFFFFFFF, 4'hF, 0, SLVERR);
    chk_read(A_LOAD, 32'h55BB77DD, OKAY, "misaligned write does not alias LOAD");
    chk_read(4'h2, 32'h0, SLVERR, "misaligned read");
    chk_read(4'hF, 32'h0, SLVERR, "misaligned read 0xF");
    do_write(A_STATUS, 32'h0, 4'hF, 0, OKAY);
    chk_read(A_STATUS, 32'h0, OKAY, "STATUS write 0");

    // T5 one-shot with irq
    do_write(A_LOAD, 32'd5, 4'hF, 0, OKAY);
    rises0 = irq_rises;
    do_write(A_CTRL, 32'h3, 4'hF, 0, OKAY);
    e_start = wr_edge;
    do_read(A_COUNT, 0);
    chk_eq(rd_data, exp_one(32'd5, rd_edge - 32'd1 - e_start), "one-shot COUNT (1)");
    do_read(A_COUNT, 0);
    chk_eq(rd_data, exp_one(32'd5, rd_edge - 32'd1 - e_start), "one-shot COUNT (2)");
    wait_for_edge(e_start + 32'd10);
    chk_eq(irq_rises - rises0, 32'd1, "one-shot: one irq rise");
    chk_eq(irq_rise, e_start + 32'd5, "one-shot: irq after edge E+N");
    chk(irq === 1'b1, "one-shot: irq high");
    chk_read(A_CTRL, 32'h2, OKAY, "one-shot: EN cleared at end");
    chk_read(A_COUNT, 32'h0, OKAY, "one-shot: COUNT 0 at end");
    chk_read(A_STATUS, 32'h1, OKAY, "one-shot: EXPIRED set");
    falls0 = irq_falls;
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);
    wait_cycles(1);
    chk_eq(irq_falls - falls0, 32'd1, "STATUS clear: irq falls");
    chk_eq(irq_fall, wr_edge, "STATUS clear: irq falls after the clear edge");
    chk_read(A_STATUS, 32'h0, OKAY, "STATUS cleared");

    // T6 LOAD = 0 one-shot
    do_write(A_LOAD, 32'd0, 4'hF, 0, OKAY);
    rises0 = irq_rises;
    do_write(A_CTRL, 32'h3, 4'hF, 0, OKAY);
    e_start = wr_edge;
    wait_cycles(3);
    chk_eq(irq_rises - rises0, 32'd1, "LOAD=0: one irq rise");
    chk_eq(irq_rise, e_start + 32'd1, "LOAD=0: ends on E+1");
    chk_read(A_COUNT, 32'h0, OKAY, "LOAD=0: COUNT 0");
    chk_read(A_CTRL, 32'h2, OKAY, "LOAD=0: EN cleared");
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);
    chk(irq === 1'b0, "LOAD=0: irq low after clear");

    // T7 periodic
    do_write(A_LOAD, 32'd3, 4'hF, 0, OKAY);
    rises0 = irq_rises;
    do_write(A_CTRL, 32'h7, 4'hF, 0, OKAY);
    e_start = wr_edge;
    for (j = 0; j < 6; j = j + 1) begin
      do_read(A_COUNT, 0);
      chk_eq(rd_data, exp_per(32'd3, rd_edge - 32'd1 - e_start), "periodic COUNT");
    end
    wait_cycles(1);
    chk_eq(irq_rises - rises0, 32'd1, "periodic: one irq rise");
    chk_eq(irq_rise, e_start + 32'd3, "periodic: first end at E+N");
    do_write(A_CTRL, 32'h6, 4'hF, 0, OKAY);
    s_edge = wr_edge;
    held = exp_per(32'd3, s_edge - e_start);
    chk_read(A_COUNT, held, OKAY, "periodic stop: COUNT held (1)");
    wait_cycles(3);
    chk_read(A_COUNT, held, OKAY, "periodic stop: COUNT held (2)");
    chk_read(A_CTRL, 32'h6, OKAY, "periodic stop: CTRL");
    chk_read(A_STATUS, 32'h1, OKAY, "periodic: EXPIRED set");
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);
    chk_read(A_STATUS, 32'h0, OKAY, "periodic: STATUS cleared");

    // T8 restart while running
    do_write(A_LOAD, 32'd10, 4'hF, 0, OKAY);
    rises0 = irq_rises;
    do_write(A_CTRL, 32'h3, 4'hF, 0, OKAY);
    do_write(A_CTRL, 32'h3, 4'hF, 0, OKAY);
    e2 = wr_edge;
    do_read(A_COUNT, 0);
    chk_eq(rd_data, exp_one(32'd10, rd_edge - 32'd1 - e2), "restart: COUNT reloaded");
    wait_for_edge(e2 + 32'd14);
    chk_eq(irq_rises - rises0, 32'd1, "restart: one irq rise");
    chk_eq(irq_rise, e2 + 32'd10, "restart: end counted from restart edge");
    chk_read(A_CTRL, 32'h2, OKAY, "restart: EN cleared at end");
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);

    // T9 STATUS clear on the end edge; IE write irq timing
    do_write(A_LOAD, 32'd4, 4'hF, 0, OKAY);
    do_write(A_CTRL, 32'h1, 4'hF, 0, OKAY);
    e_start = wr_edge;
    wait_for_edge(e_start + 32'd4);
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);
    chk_eq(wr_edge, e_start + 32'd4, "end-beats-clear: clear lands on end edge");
    chk_read(A_STATUS, 32'h1, OKAY, "end-beats-clear: EXPIRED stays set");
    chk_read(A_CTRL, 32'h0, OKAY, "end-beats-clear: EN cleared");
    chk(irq === 1'b0, "IE=0 masks irq");
    rises0 = irq_rises;
    do_write(A_CTRL, 32'h2, 4'hF, 0, OKAY);
    wait_cycles(1);
    chk_eq(irq_rises - rises0, 32'd1, "IE write: irq rises");
    chk_eq(irq_rise, wr_edge, "IE write: irq after the IE write edge");
    falls0 = irq_falls;
    do_write(A_CTRL, 32'h0, 4'hF, 0, OKAY);
    wait_cycles(1);
    chk_eq(irq_falls - falls0, 32'd1, "IE clear: irq falls");
    chk_eq(irq_fall, wr_edge, "IE clear: irq after the IE write edge");
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);
    chk_read(A_STATUS, 32'h0, OKAY, "STATUS cleared after T9");

    // T10 CTRL EN=1 on the end edge restarts
    do_write(A_CTRL, 32'h1, 4'hF, 0, OKAY);
    e_start = wr_edge;
    wait_for_edge(e_start + 32'd4);
    do_write(A_CTRL, 32'h1, 4'hF, 0, OKAY);
    e2 = wr_edge;
    chk_eq(e2, e_start + 32'd4, "ctrl-wins: write lands on end edge");
    do_read(A_COUNT, 0);
    chk_eq(rd_data, exp_one(32'd4, rd_edge - 32'd1 - e2), "ctrl-wins EN=1: restarted from LOAD");
    chk_read(A_STATUS, 32'h1, OKAY, "ctrl-wins EN=1: EXPIRED set");
    wait_for_edge(e2 + 32'd10);
    chk_read(A_CTRL, 32'h0, OKAY, "ctrl-wins EN=1: second end clears EN");
    chk_read(A_COUNT, 32'h0, OKAY, "ctrl-wins EN=1: COUNT 0 after second end");
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);

    // T11 periodic, CTRL EN=0 on the end edge
    do_write(A_CTRL, 32'h5, 4'hF, 0, OKAY);
    e_start = wr_edge;
    wait_for_edge(e_start + 32'd4);
    do_write(A_CTRL, 32'h4, 4'hF, 0, OKAY);
    chk_read(A_COUNT, 32'd4, OKAY, "ctrl-wins EN=0 periodic: COUNT = LOAD");
    wait_cycles(3);
    chk_read(A_COUNT, 32'd4, OKAY, "ctrl-wins EN=0 periodic: COUNT held");
    chk_read(A_CTRL, 32'h4, OKAY, "ctrl-wins EN=0 periodic: CTRL");
    chk_read(A_STATUS, 32'h1, OKAY, "ctrl-wins EN=0 periodic: EXPIRED set");
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);

    // T11b LOAD write on a periodic end edge: either value accepted
    do_write(A_CTRL, 32'h5, 4'hF, 0, OKAY);
    e_start = wr_edge;
    wait_for_edge(e_start + 32'd4);
    do_write(A_LOAD, 32'd9, 4'hF, 0, OKAY);
    do_read(A_COUNT, 0);
    chk_eq(rd_edge, e_start + 32'd6, "load-end-edge: read timing");
    chk(rd_data === 32'd3 || rd_data === 32'd8, "load-end-edge: reload took old or new LOAD");
    do_write(A_CTRL, 32'h0, 4'hF, 0, OKAY);
    do_write(A_STATUS, 32'h1, 4'hF, 0, OKAY);
    chk_read(A_LOAD, 32'd9, OKAY, "load-end-edge: LOAD written");

    // T12 AW first
    awaddr = A_LOAD; awvalid = 1'b1;
    chk(awready === 1'b1, "AW first: awready");
    @(negedge aclk);
    awvalid = 1'b0;
    chk(awready === 1'b0 && wready === 1'b1 && bvalid === 1'b0, "AW first: AW held, no B");
    repeat (2) begin
      @(negedge aclk);
      chk(bvalid === 1'b0 && awready === 1'b0, "AW first: waiting for W");
    end
    wdata = 32'h0BADF00D; wstrb = 4'hF; wvalid = 1'b1;
    chk(wready === 1'b1, "AW first: wready");
    @(negedge aclk);
    wvalid = 1'b0;
    chk(bvalid === 1'b1 && bresp === OKAY, "AW first: B after W");
    chk(awready === 1'b0 && wready === 1'b0, "AW first: readies low while B waits");
    bready = 1'b1;
    @(negedge aclk);
    bready = 1'b0;
    chk(bvalid === 1'b0 && awready === 1'b1 && wready === 1'b1, "AW first: idle after B");
    chk_read(A_LOAD, 32'h0BADF00D, OKAY, "AW first: LOAD");

    // T12b W first, partial strobe
    wdata = 32'h600DCAFE; wstrb = 4'b0011; wvalid = 1'b1;
    chk(wready === 1'b1, "W first: wready");
    @(negedge aclk);
    wvalid = 1'b0;
    chk(wready === 1'b0 && awready === 1'b1 && bvalid === 1'b0, "W first: W held, no B");
    repeat (2) begin
      @(negedge aclk);
      chk(bvalid === 1'b0 && wready === 1'b0, "W first: waiting for AW");
    end
    awaddr = A_LOAD; awvalid = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0;
    chk(bvalid === 1'b1 && bresp === OKAY, "W first: B after AW");
    bready = 1'b1;
    @(negedge aclk);
    bready = 1'b0;
    chk(bvalid === 1'b0, "W first: idle after B");
    chk_read(A_LOAD, 32'h0BADCAFE, OKAY, "W first: held strobes applied");

    // T12c W first to COUNT: SLVERR via held path
    wdata = 32'hFFFFFFFF; wstrb = 4'hF; wvalid = 1'b1;
    @(negedge aclk);
    wvalid = 1'b0;
    awaddr = A_COUNT; awvalid = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0;
    chk(bvalid === 1'b1 && bresp === SLVERR, "W first to COUNT: SLVERR");
    bready = 1'b1;
    @(negedge aclk);
    bready = 1'b0;

    // T13 read and write on the same edge
    awaddr = A_LOAD; wdata = 32'hCAFEF00D; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
    araddr = A_LOAD; arvalid = 1'b1;
    chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, "same edge: all ready");
    @(negedge aclk);
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    chk(bvalid === 1'b1 && bresp === OKAY, "same edge: B");
    chk(rvalid === 1'b1 && rresp === OKAY, "same edge: R");
    chk_eq(rdata, 32'h0BADCAFE, "same edge: read returns pre-edge LOAD");
    bready = 1'b1; rready = 1'b1;
    @(negedge aclk);
    bready = 1'b0; rready = 1'b0;
    chk(bvalid === 1'b0 && rvalid === 1'b0, "same edge: both handshakes done");
    chk_read(A_LOAD, 32'hCAFEF00D, OKAY, "same edge: write applied");

    // T14 R stability while counting; stop; stopped EN=0 write
    do_write(A_LOAD, 32'd100, 4'hF, 0, OKAY);
    do_write(A_CTRL, 32'h1, 4'hF, 0, OKAY);
    e_start = wr_edge;
    do_read(A_COUNT, 6);
    chk_eq(rd_data, exp_one(32'd100, rd_edge - 32'd1 - e_start), "stalled read: COUNT at accept");
    do_read(4'h9, 3);
    chk(rd_data === 32'h0 && rd_resp === SLVERR, "stalled unmapped read");
    do_write(A_STATUS, 32'h0, 4'hF, 4, OKAY);
    do_write(A_CTRL, 32'h0, 4'hF, 0, OKAY);
    s_edge = wr_edge;
    held = exp_one(32'd100, s_edge - e_start);
    chk_read(A_COUNT, held, OKAY, "stop: COUNT held (1)");
    do_write(A_CTRL, 32'h0, 4'hF, 0, OKAY);
    chk_read(A_COUNT, held, OKAY, "stop: EN=0 while stopped keeps COUNT");

    // T15 ready-high responses last one cycle
    bready = 1'b1;
    awaddr = A_STATUS; wdata = 32'h0; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0; wvalid = 1'b0;
    chk(bvalid === 1'b1, "bready high: bvalid still raised");
    @(negedge aclk);
    chk(bvalid === 1'b0, "bready high: bvalid one cycle");
    bready = 1'b0;
    rready = 1'b1;
    araddr = A_LOAD; arvalid = 1'b1;
    @(negedge aclk);
    arvalid = 1'b0;
    chk(rvalid === 1'b1 && rdata === 32'd100, "rready high: rvalid still raised");
    @(negedge aclk);
    chk(rvalid === 1'b0, "rready high: rvalid one cycle");
    rready = 1'b0;

    // T16 reset during traffic
    do_write(A_CTRL, 32'h2, 4'hF, 0, OKAY);
    awaddr = A_STATUS; wdata = 32'h0; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
    araddr = A_LOAD; arvalid = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    chk(bvalid === 1'b1 && rvalid === 1'b1, "pre-reset: responses pending");
    aresetn = 1'b0;
    @(negedge aclk);
    aresetn = 1'b1;
    chk(bvalid === 1'b0 && rvalid === 1'b0 && irq === 1'b0, "reset in traffic: valids and irq low");
    chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, "reset in traffic: readies high");
    chk_read(A_LOAD, 32'h0, OKAY, "reset in traffic: LOAD 0");
    chk_read(A_CTRL, 32'h0, OKAY, "reset in traffic: CTRL 0");
    awaddr = A_LOAD; awvalid = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0;
    chk(awready === 1'b0, "reset in traffic: AW held before reset");
    aresetn = 1'b0;
    @(negedge aclk);
    aresetn = 1'b1;
    chk(awready === 1'b1 && wready === 1'b1, "reset clears held AW");
    wdata = 32'h12345678; wstrb = 4'hF; wvalid = 1'b1;
    @(negedge aclk);
    wvalid = 1'b0;
    chk(bvalid === 1'b0 && wready === 1'b0, "after reset: W waits for its own AW");
    awaddr = A_LOAD; awvalid = 1'b1;
    @(negedge aclk);
    awvalid = 1'b0;
    chk(bvalid === 1'b1 && bresp === OKAY, "after reset: write completes");
    bready = 1'b1;
    @(negedge aclk);
    bready = 1'b0;
    chk_read(A_LOAD, 32'h12345678, OKAY, "after reset: LOAD written");

    // verdict
    wait_cycles(2);
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = "unset";
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
